/**
 * Synthetic palsy bench (dev only, tools/blender/BENCH.md): reads public/_bench/manifest.json
 * (git-ignored renders with a known ratio w), runs the photo-set path (detectImage →
 * analyzeSession, analyzeCoupling for synkinesis) and lists measured vs true ratio as a CSV.
 *
 * Geometric truth: every detected rest landmark is pinned to the rendered mesh triangle under it
 * (projected vertices exported by bench_render.py) and followed through the expression; the same
 * analysis on these perfectly tracked points gives the ratio the app's measure definition yields.
 * detected − geometric = landmark-model error, geometric − w = measure definition vs key value.
 */
import { useEffect, useRef, useState } from 'preact/hooks';
import {
  LID_TRACKED_MIN,
  MOVEMENT_TASKS,
  analyzeCoupling,
  analyzeSession,
  DEFAULT_QUALITY,
  assessFrame,
  type CouplingExpression,
  type QualityThresholds,
  type FrameObservation,
  type MovementTaskId,
  type SidePair,
} from '../../core';
import { download } from '../../data/export';
import { mirrorClosures } from '../../vision/mirror';
import { AppBar, Notice } from '../components/common';
import { ISSUE_LABEL, TASK_SHORT } from '../labels';
import { CaptureTracker } from '../../vision/captureTracker';
import { applySimilarity, fitSimilarity } from '../../core/geometry';
import { ALIGNMENT_ANCHORS, SIDE, type SideIndices } from '../../core/landmarks';

type Slot = 'rest' | MovementTaskId;

interface BenchSet {
  person: string;
  condition: string;
  /** True ratio (null for real photos: no ground truth). */
  w: number | null;
  variant: string;
  /** Condition mesh: triangles over the visible skin vertices ({tris, n}). */
  mesh?: string;
  images: Partial<Record<Slot, string>>;
  /** Real videos: candidate frames per task; the one with the largest movement (both sides) replaces `images[task]`. */
  pick?: Partial<Record<MovementTaskId, string[]>>;
  /** Real photos with ground truth: the patient's left half of each expression photo is replaced by the aligned rest photo (w = 0). */
  synth?: 'restLeft';
}

interface Row {
  person: string;
  condition: string;
  variant: string;
  task: MovementTaskId;
  w: number | null;
  ratio: number | null;
  /** Ratio from the mesh-tracked landmarks (null without mesh data). */
  geo: number | null;
  /** Ratio from the rest landmarks tracked into the expression by optical flow. */
  trk: number | null;
  /** Share of face-mesh points the tracker kept (the rest fall back to detection). */
  kept: number | null;
  /** Time of the app's tracker (CaptureTracker.track) for this image, ms. */
  trkMs: number | null;
  /** Ratios and excursions from external point trackers (tools/bench/ext_track.py), per method; absent when not run. */
  ext: Record<string, number | null>;
  extExc: Record<string, SidePair | null>;
  /** External tracker time per image (GPU, from its JSON), ms. */
  extMs: Record<string, number | null>;
  /** Per-side excursion (affected left, healthy right) for detection / geometric / tracking. */
  exc: Record<'det' | 'geo' | 'trk', SidePair | null>;
  /** Observations for the overlay view (not exported). */
  vis: { restFile: string; file: string; rest: FrameObservation; det: FrameObservation; trk?: FrameObservation; geo?: FrameObservation };
  yaw: number;
  pitch: number;
  roll: number;
  gateOk: boolean;
  gateReasons: string;
  synk: string;
  geoSynk: string;
  trkSynk: string;
}

/**
 * External point trackers compared with the app's tracker (tools/bench/README.md). public/_bench/ext/_index.json lists
 * the runs of tools/bench/ext_track.py; each run's tracks (rest landmarks 0–467 tracked into the expression) are read
 * from public/_bench/ext/<run>/<expression image>.json. A run name is the model, optionally with _<input size>.
 */
const EXT_LABEL: Record<string, string> = { alltracker: 'AllTracker', alltracker_tiny: 'AllTracker 경량', bootstapir: 'BootsTAPIR' };
const extLabel = (k: string): string => {
  const m = /^(.+)_(\d+)$/.exec(k);
  return EXT_LABEL[k] ?? (m && EXT_LABEL[m[1]!] ? `${EXT_LABEL[m[1]!]} ${m[2]}px` : k);
};

/** Bench task → synkinesis-finder expression (snarl has none). */
const SYNK_EXPR: Partial<Record<MovementTaskId, CouplingExpression>> = {
  brow: 'brow',
  eyeClose: 'eyeGentle',
  smile: 'smileClosed',
  pucker: 'pucker',
};
const TOL = 0.05;
const DIR = `${import.meta.env.BASE_URL}_bench/`;

/** Synthetic images made in the browser: key → blob URL. */
const SYNTH = new Map<string, string>();
// Dev automation: the synthetic images (data URLs) for scripted analyses of the bench rows.
(window as unknown as { __benchSynth?: Map<string, string> }).__benchSynth = SYNTH;
const srcOf = (file: string) => SYNTH.get(file) ?? DIR + file;

/**
 * The expression photo with the patient's left half taken from the rest photo, which is first aligned to the
 * expression's head position on the rigid anchors. Feathered over ±FEATHER eye distances around the midline.
 */
async function halfRest(rest: { obs: FrameObservation; img: HTMLImageElement }, expr: { obs: FrameObservation; img: HTMLImageElement }) {
  const FEATHER = 0.06;
  const px = (o: FrameObservation, i: number) => ({ x: o.landmarks[3 * i]! * o.width, y: o.landmarks[3 * i + 1]! * o.height });
  const T = fitSimilarity(
    ALIGNMENT_ANCHORS.map((i) => px(rest.obs, i)),
    ALIGNMENT_ANCHORS.map((i) => px(expr.obs, i)),
  );
  const { width: W, height: H } = expr.obs;
  const mk = () => {
    const c = document.createElement('canvas');
    [c.width, c.height] = [W, H];
    return [c, c.getContext('2d', { willReadFrequently: true })!] as const;
  };
  const [out, o] = mk();
  o.drawImage(expr.img, 0, 0);
  const [, w] = mk();
  w.setTransform(T.s * T.c, T.s * T.sn, -T.s * T.sn, T.s * T.c, T.tx, T.ty);
  w.drawImage(rest.img, 0, 0);
  const mid = (i: number, j: number) => ({
    x: (px(expr.obs, i).x + px(expr.obs, j).x) / 2,
    y: (px(expr.obs, i).y + px(expr.obs, j).y) / 2,
  });
  const eR = mid(SIDE.right.eyeOuter, SIDE.right.eyeInner);
  const eL = mid(SIDE.left.eyeOuter, SIDE.left.eyeInner);
  const d = Math.hypot(eL.x - eR.x, eL.y - eR.y);
  const [ux, uy] = [(eL.x - eR.x) / d, (eL.y - eR.y) / d];
  const [mx, my] = [(eL.x + eR.x) / 2, (eL.y + eR.y) / 2];
  const a = o.getImageData(0, 0, W, H);
  const b = w.getImageData(0, 0, W, H).data;
  for (let y = 0; y < H; y++)
    for (let x = 0; x < W; x++) {
      const t = Math.min(1, Math.max(0, ((x - mx) * ux + (y - my) * uy) / (FEATHER * d) / 2 + 0.5));
      if (t === 0) continue;
      const k = 4 * (y * W + x);
      for (let ch = 0; ch < 3; ch++) a.data[k + ch] = a.data[k + ch]! * (1 - t) + b[k + ch]! * t;
    }
  o.putImageData(a, 0, 0);
  const blob = await new Promise<Blob>((res) => out.toBlob((x) => res(x!), 'image/png'));
  return URL.createObjectURL(blob);
}

function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`image load failed: ${src}`));
    img.src = src;
  });
}

const getJson = async <T,>(file: string): Promise<T> => {
  const res = await fetch(DIR + file, { cache: 'no-store' });
  if (!res.ok) throw new Error(file);
  return (await res.json()) as T;
};

const diff = (a: number | null, b: number | null): number | null => (a == null || b == null ? null : a - b);
const r3 = (x: number | null): string => (x == null ? '' : x.toFixed(3));
const columns = (ext: string[]): [string, (r: Row) => string][] => [
  ['person', (r) => r.person],
  ['condition', (r) => r.condition],
  ['variant', (r) => r.variant],
  ['task', (r) => r.task],
  ['file', (r) => r.vis.file],
  ['w_true', (r) => (r.w == null ? '' : String(r.w))],
  ['ratio', (r) => r3(r.ratio)],
  ['ratio_geometric', (r) => r3(r.geo)],
  ['error_vs_w', (r) => r3(diff(r.ratio, r.w))],
  ['error_vs_geometric', (r) => r3(diff(r.ratio, r.geo))],
  ['geometric_vs_w', (r) => r3(diff(r.geo, r.w))],
  ['ratio_tracked', (r) => r3(r.trk)],
  ['tracked_vs_geometric', (r) => r3(diff(r.trk, r.geo))],
  ['tracked_share', (r) => r3(r.kept)],
  ['tracked_ms', (r) => (r.trkMs == null ? '' : r.trkMs.toFixed(1))],
  ...ext.map((m): [string, (r: Row) => string] => [`ratio_${m}`, (r) => r3(r.ext[m] ?? null)]),
  ...(['det', 'geo', 'trk'] as const).flatMap((m) =>
    (['left', 'right'] as const).map((sd): [string, (r: Row) => string] => [
      `exc_${m}_${sd}`,
      (r) => (r.exc[m] ? r.exc[m]![sd].toFixed(4) : ''),
    ]),
  ),
  ['yaw', (r) => r.yaw.toFixed(1)],
  ['pitch', (r) => r.pitch.toFixed(1)],
  ['roll', (r) => r.roll.toFixed(1)],
  ['gate_ok', (r) => (r.gateOk ? '1' : '0')],
  ['gate_reasons', (r) => r.gateReasons],
  ['synkinesis', (r) => r.synk],
  ['synkinesis_geometric', (r) => r.geoSynk],
  ['synkinesis_tracked', (r) => r.trkSynk],
];
interface Method {
  k: string;
  label: string;
  ratio: (r: Row) => number | null;
  exc: (r: Row) => SidePair | null;
}
/** Every way the bench measured the rows, for the comparison tables. */
const methodsOf = (ext: string[]): Method[] => [
  { k: 'det', label: '검출', ratio: (r) => r.ratio, exc: (r) => r.exc.det },
  { k: 'trk', label: '추적(앱)', ratio: (r) => r.trk, exc: (r) => r.exc.trk },
  ...ext.map((m) => ({ k: m, label: extLabel(m), ratio: (r: Row) => r.ext[m] ?? null, exc: (r: Row) => r.extExc[m] ?? null })),
  { k: 'geo', label: '3D 정답', ratio: (r) => r.geo, exc: (r) => r.exc.geo },
];
const extRuns = (rows: Row[]): string[] => [...new Set(rows.flatMap((r) => Object.keys(r.ext)))];
const csvCell = (s: string): string => (/[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s);

/** Per landmark: mesh vertex indices and barycentric weights under it in the rest render. */
type Pin = [number[], number[]] | null;

function pinLandmarks(rest: FrameObservation, xy: number[], tris: number[]): Pin[] {
  const pins: Pin[] = [];
  const n = Math.min(468, Math.floor(rest.landmarks.length / 3)); // iris points (468+) sit on the eyeball, not the skin
  for (let i = 0; i < n; i++) {
    const px = rest.landmarks[3 * i]! * rest.width;
    const py = rest.landmarks[3 * i + 1]! * rest.height;
    let pin: Pin = null;
    for (let t = 0; t < tris.length && !pin; t += 3) {
      const [a, b, c] = [tris[t]!, tris[t + 1]!, tris[t + 2]!];
      const [ax, ay, bx, by, cx, cy] = [xy[2 * a]!, xy[2 * a + 1]!, xy[2 * b]!, xy[2 * b + 1]!, xy[2 * c]!, xy[2 * c + 1]!];
      const det = (by - cy) * (ax - cx) + (cx - bx) * (ay - cy);
      if (Math.abs(det) < 1e-9) continue;
      const l1 = ((by - cy) * (px - cx) + (cx - bx) * (py - cy)) / det;
      const l2 = ((cy - ay) * (px - cx) + (ax - cx) * (py - cy)) / det;
      const l3 = 1 - l1 - l2;
      if (l1 >= -1e-6 && l2 >= -1e-6 && l3 >= -1e-6)
        pin = [
          [a, b, c],
          [l1, l2, l3],
        ];
    }
    if (!pin) {
      let best = -1;
      let bd = Infinity;
      for (let v = 0; v < xy.length / 2; v++) {
        const d = (xy[2 * v]! - px) ** 2 + (xy[2 * v + 1]! - py) ** 2;
        if (d < bd) [bd, best] = [d, v];
      }
      if (best >= 0 && bd < 25) pin = [[best], [1]];
    }
    pins.push(pin);
  }
  return pins;
}

/** The rest detection with every pinned landmark moved to where its mesh point went. */
function tracked(rest: FrameObservation, pins: Pin[], restXy: number[], xy: number[]): FrameObservation {
  const lm = Array.from(rest.landmarks);
  pins.forEach((pin, i) => {
    if (!pin) return;
    const [vs, ws] = pin;
    let dx = 0;
    let dy = 0;
    vs.forEach((v, k) => {
      dx += ws[k]! * (xy[2 * v]! - restXy[2 * v]!);
      dy += ws[k]! * (xy[2 * v + 1]! - restXy[2 * v + 1]!);
    });
    lm[3 * i] = lm[3 * i]! + dx / rest.width;
    lm[3 * i + 1] = lm[3 * i + 1]! + dy / rest.height;
  });
  return { ...rest, landmarks: lm };
}

/**
 * The rest landmarks moved to where an external tracker put the face-mesh points (xy: expression-image pixels); the iris
 * follows the head (similarity on the rigid anchors), as in CaptureTracker. Pose and quality come from the expression's detection.
 */
function external(rest: FrameObservation, det: FrameObservation, xy: number[]): FrameObservation {
  const lm = Array.from(rest.landmarks);
  const n = Math.min(468, Math.floor(xy.length / 2));
  for (let i = 0; i < n; i++) {
    lm[3 * i] = xy[2 * i]! / det.width;
    lm[3 * i + 1] = xy[2 * i + 1]! / det.height;
  }
  const restPx = (i: number) => ({ x: rest.landmarks[3 * i]! * rest.width, y: rest.landmarks[3 * i + 1]! * rest.height });
  const T = fitSimilarity(
    ALIGNMENT_ANCHORS.map(restPx),
    ALIGNMENT_ANCHORS.map((i) => ({ x: lm[3 * i]! * det.width, y: lm[3 * i + 1]! * det.height })),
  );
  for (let i = 468; i < lm.length / 3; i++) {
    const q = applySimilarity(T, restPx(i));
    lm[3 * i] = q.x / det.width;
    lm[3 * i + 1] = q.y / det.height;
  }
  return { ...det, landmarks: lm };
}

/** Research only: measure frames the gate would reject (the gate column still shows the real verdict). */
const OPEN_GATE: QualityThresholds = {
  ...DEFAULT_QUALITY,
  maxYawDeg: 90,
  maxPitchDeg: 90,
  maxRollDeg: 90,
  minEyeDistanceFrac: 0,
  minEyeDistancePx: 0,
  edgeMargin: -1,
  minLuminance: 0,
  maxLuminance: 256,
  maxLuminanceAsymmetry: Infinity,
};

function measure(rest: FrameObservation, obs: Partial<Record<MovementTaskId, FrameObservation>>, quality?: QualityThresholds) {
  const a = analyzeSession({
    affectedSide: 'left',
    mode: 'photo',
    quality,
    rest: [rest],
    tasks: Object.fromEntries(Object.entries(obs).map(([t, o]) => [t, [o]])),
  });
  // The finder needs ≥ 5 valid frames per expression; a still counts as five identical frames.
  const five = (o: FrameObservation) => [o, o, o, o, o];
  const c = analyzeCoupling({
    affectedSide: 'left',
    quality,
    rest: five(rest),
    expressions: Object.fromEntries(
      Object.entries(obs).flatMap(([t, o]) => (SYNK_EXPR[t as MovementTaskId] ? [[SYNK_EXPR[t as MovementTaskId]!, five(o)]] : [])),
    ),
  });
  const synk = (t: MovementTaskId): string => {
    const expr = SYNK_EXPR[t];
    if (!expr) return '';
    if (c.missing.includes(expr)) return '측정 안 됨';
    return (
      c.findings
        .filter((f) => f.expression === expr)
        .map((f) => `${f.region} ×${f.severity.toFixed(1)}`)
        .join(' ') || '없음'
    );
  };
  return { a, synk };
}

async function runBench(sets: BenchSet[], onMsg: (m: string) => void, ignoreGate = false): Promise<Row[]> {
  const qt = ignoreGate ? OPEN_GATE : undefined;
  const extNames = await getJson<string[]>('ext/_index.json').catch((): string[] => []);
  const { getEngine } = await import('../../vision/landmarker');
  const engine = await getEngine(onMsg);
  const cache = new Map<string, { obs: FrameObservation; img: HTMLImageElement }>();
  const run = Date.now(); // re-renders keep the file names: bypass the browser's image cache
  const load = async (file: string) => {
    if (!cache.has(file)) {
      const img = await loadImage(SYNTH.get(file) ?? `${DIR}${file}?v=${run}`);
      cache.set(file, { obs: await engine.detectImage(img), img });
    }
    return cache.get(file)!;
  };
  const tk = new CaptureTracker();
  const detect = async (file: string) => (await load(file)).obs;
  const xyOf = async (png: string) => (await getJson<{ xy: number[] }>(png.replace(/\.png$/, '.mesh.json'))).xy;
  const rows: Row[] = [];
  for (const [i, s] of sets.entries()) {
    onMsg(`${i + 1}/${sets.length} ${s.person} · ${s.condition} · w ${s.w} · ${s.variant}`);
    const rest = await detect(s.images.rest!);
    for (const [t, files] of Object.entries(s.pick ?? {}) as [MovementTaskId, string[]][]) {
      let best = -1;
      for (const [k, f] of files.entries()) {
        onMsg(`${i + 1}/${sets.length} ${s.person} · ${TASK_SHORT[t]} 최고점 찾기 ${k + 1}/${files.length}`);
        const e = measure(rest, { [t]: await detect(f) }, qt).a.tasks[t]?.excursion;
        if (e && e.left + e.right > best) [best, s.images[t]] = [e.left + e.right, f];
      }
    }
    if (s.synth === 'restLeft' && rest.landmarks.length)
      for (const t of MOVEMENT_TASKS) {
        const f = s.images[t];
        if (!f || !(await detect(f)).landmarks.length) continue;
        const key = `synth/${s.person}/${t}.png`;
        if (!SYNTH.has(key)) SYNTH.set(key, await halfRest(await load(s.images.rest!), await load(f)));
        s.images[t] = key;
      }
    const obs: Partial<Record<MovementTaskId, FrameObservation>> = {};
    for (const t of MOVEMENT_TASKS) if (s.images[t]) obs[t] = await detect(s.images[t]!);
    const det = measure(rest, obs, qt);

    let geo: ReturnType<typeof measure> | null = null;
    const gobs: Partial<Record<MovementTaskId, FrameObservation>> = {};
    if (s.mesh && rest.landmarks.length) {
      const { tris } = await getJson<{ tris: number[] }>(s.mesh);
      const restXy = await xyOf(s.images.rest!);
      const pins = pinLandmarks(rest, restXy, tris);
      for (const t of MOVEMENT_TASKS) if (s.images[t]) gobs[t] = tracked(rest, pins, restXy, await xyOf(s.images[t]!));
      geo = measure(rest, gobs, qt);
    }

    let trk: ReturnType<typeof measure> | null = null;
    const kept: Partial<Record<MovementTaskId, number>> = {};
    const trkMs: Partial<Record<MovementTaskId, number>> = {};
    const tobs: Partial<Record<MovementTaskId, FrameObservation>> = {};
    if (rest.landmarks.length) {
      // Same path as the app's photo set and video assessment (CaptureTracker).
      tk.setRef((await load(s.images.rest!)).img, rest);
      for (const t of MOVEMENT_TASKS)
        if (obs[t]?.landmarks.length) {
          const t0 = performance.now();
          const gray = tk.grab((await load(s.images[t]!)).img, obs[t]!);
          tobs[t] = gray ? tk.track({ obs: obs[t]!, gray }) : obs[t]!;
          trkMs[t] = performance.now() - t0;
          kept[t] = tk.lastKept;
          // FPA-GEOM 0.5.0: eyes whose lid points were not tracked are measured on their mirror composites (as in the app).
          const lt = tobs[t]!.lidTracked;
          if (t === 'eyeClose' && gray && tk.ref?.gray && lt && Math.min(lt.left, lt.right) < LID_TRACKED_MIN) {
            const [m] = await mirrorClosures(tk.ref, tk.ref.gray, [gray], (c) => engine.detectImage(c));
            if (m) tobs[t] = { ...tobs[t]!, mirrorClosure: m };
          }
        }
      trk = measure(rest, tobs, qt);
    }

    const ext: Record<string, ReturnType<typeof measure>> = {};
    const extMs: Record<string, Partial<Record<MovementTaskId, number | null>>> = {};
    if (rest.landmarks.length)
      for (const m of extNames) {
        const eobs: Partial<Record<MovementTaskId, FrameObservation>> = {};
        for (const t of MOVEMENT_TASKS) {
          if (!obs[t]?.landmarks.length) continue;
          const tr = await getJson<{ xy: number[]; ms?: number }>(`ext/${m}/${s.images[t]}.json`).catch(() => null);
          if (tr) {
            eobs[t] = external(rest, obs[t]!, tr.xy);
            (extMs[m] ??= {})[t] = tr.ms ?? null;
          }
        }
        if (Object.keys(eobs).length) ext[m] = measure(rest, eobs, qt);
      }

    const restQ = assessFrame(rest);
    for (const t of MOVEMENT_TASKS) {
      if (!obs[t]) continue;
      const q = assessFrame(obs[t]!);
      const reasons = [...restQ.issues.map((x) => `안정:${ISSUE_LABEL[x]}`), ...q.issues.map((x) => ISSUE_LABEL[x])];
      for (const e of det.a.errors.filter((e) => e.task === t)) reasons.push(e.code);
      for (const e of trk?.a.errors.filter((e) => e.task === t || !e.task) ?? []) reasons.push(`추적:${e.code}`);
      for (const w of trk?.a.warnings.filter((w) => w.task === t) ?? []) reasons.push(`추적:${w.code}`);
      rows.push({
        person: s.person,
        condition: s.condition,
        variant: s.variant,
        task: t,
        w: s.w,
        ratio: det.a.tasks[t]?.ratio ?? null,
        geo: geo?.a.tasks[t]?.ratio ?? null,
        trk: trk?.a.tasks[t]?.ratio ?? null,
        kept: kept[t] ?? null,
        trkMs: trkMs[t] ?? null,
        ext: Object.fromEntries(extNames.filter((m) => ext[m]).map((m) => [m, ext[m]!.a.tasks[t]?.ratio ?? null])),
        extExc: Object.fromEntries(extNames.filter((m) => ext[m]).map((m) => [m, ext[m]!.a.tasks[t]?.excursion ?? null])),
        extMs: Object.fromEntries(extNames.filter((m) => ext[m]).map((m) => [m, extMs[m]?.[t] ?? null])),
        vis: { restFile: s.images.rest!, file: s.images[t]!, rest, det: obs[t]!, trk: tobs[t], geo: gobs[t] },
        exc: { det: det.a.tasks[t]?.excursion ?? null, geo: geo?.a.tasks[t]?.excursion ?? null, trk: trk?.a.tasks[t]?.excursion ?? null },
        ...q.pose,
        gateOk: restQ.ok && q.ok,
        gateReasons: reasons.join(', '),
        synk: det.synk(t),
        geoSynk: geo?.synk(t) ?? '',
        trkSynk: trk?.synk(t) ?? '',
      });
    }
  }
  return rows;
}

/** Points each task's measure reads (per side). */
const MEASURED: Record<MovementTaskId, (s: SideIndices) => number[]> = {
  brow: (s) => [...s.brow],
  eyeClose: (s) => s.lidPairs.flat(),
  smile: (s) => [s.mouthCorner],
  snarl: (s) => [...s.ala, ...s.upperLip],
  pucker: (s) => [s.mouthCorner],
};
const METHOD = [
  { k: 'geo', color: '#3e63dd', label: '3D 정답' },
  { k: 'det', color: '#e5484d', label: '검출' },
  { k: 'trk', color: '#30a46c', label: '추적' },
] as const;
const GAIN = 3;

/** Expression photo zoomed on the face: rest → expression movement of the measured points, per method (×GAIN). */
function Overlay({ row, onClose }: { row: Row; onClose: () => void }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    let live = true;
    (async () => {
      const v = row.vis;
      const img = await loadImage(srcOf(v.file));
      const c = ref.current;
      if (!live || !c) return;
      const at = (o: FrameObservation, i: number) => ({ x: o.landmarks[3 * i]! * o.width, y: o.landmarks[3 * i + 1]! * o.height });
      let [x0, y0, x1, y1] = [Infinity, Infinity, -Infinity, -Infinity];
      for (let i = 0; i < 468; i++) {
        const p = at(v.det, i);
        [x0, y0, x1, y1] = [Math.min(x0, p.x), Math.min(y0, p.y), Math.max(x1, p.x), Math.max(y1, p.y)];
      }
      const pad = 0.12 * (x1 - x0);
      [x0, y0, x1, y1] = [x0 - pad, y0 - pad, x1 + pad, y1 + pad];
      const W = 900;
      const k = W / (x1 - x0);
      c.width = W;
      c.height = Math.round((y1 - y0) * k);
      const ctx = c.getContext('2d')!;
      ctx.drawImage(img, x0, y0, x1 - x0, y1 - y0, 0, 0, W, c.height);
      ctx.fillStyle = 'rgba(0,0,0,0.25)';
      ctx.fillRect(0, 0, W, c.height);
      const toC = (p: { x: number; y: number }) => ({ x: (p.x - x0) * k, y: (p.y - y0) * k });
      // Rest points carried into the expression photo by the head motion (rigid anchors).
      const T = fitSimilarity(
        ALIGNMENT_ANCHORS.map((i) => at(v.rest, i)),
        ALIGNMENT_ANCHORS.map((i) => at(v.det, i)),
      );
      for (const side of ['right', 'left'] as const) {
        for (const i of MEASURED[row.task](SIDE[side])) {
          const a = toC(applySimilarity(T, at(v.rest, i)));
          for (const m of METHOD) {
            const o = v[m.k];
            if (!o) continue;
            const b = toC(at(o, i));
            const tip = { x: a.x + GAIN * (b.x - a.x), y: a.y + GAIN * (b.y - a.y) };
            ctx.strokeStyle = ctx.fillStyle = m.color;
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(a.x, a.y);
            ctx.lineTo(tip.x, tip.y);
            ctx.stroke();
            const ang = Math.atan2(tip.y - a.y, tip.x - a.x);
            if (Math.hypot(tip.x - a.x, tip.y - a.y) > 6) {
              ctx.beginPath();
              ctx.moveTo(tip.x, tip.y);
              ctx.lineTo(tip.x - 11 * Math.cos(ang - 0.45), tip.y - 11 * Math.sin(ang - 0.45));
              ctx.lineTo(tip.x - 11 * Math.cos(ang + 0.45), tip.y - 11 * Math.sin(ang + 0.45));
              ctx.fill();
            }
          }
          ctx.fillStyle = '#fff';
          ctx.beginPath();
          ctx.arc(a.x, a.y, 3.5, 0, 2 * Math.PI);
          ctx.fill();
        }
      }
      ctx.font = 'bold 26px sans-serif';
      ctx.fillStyle = '#fff';
      ctx.fillText('오른쪽 (건측)', 16, 36);
      ctx.textAlign = 'right';
      ctx.fillText('왼쪽 (마비측)', W - 16, 36);
    })();
    return () => {
      live = false;
    };
  }, [row]);
  return (
    <div class="card tight">
      <div class="row" style={{ justifyContent: 'space-between' }}>
        <h3>
          {TASK_SHORT[row.task]} · {row.person}·{row.condition} · w {row.w ?? '–'}
        </h3>
        <span class="small muted">
          {row.vis.restFile.split('/').pop()} → {row.vis.file.split('/').pop()}
        </span>
        <button class="btn sm ghost" onClick={onClose}>
          닫기
        </button>
      </div>
      <canvas ref={ref} style={{ width: '100%', borderRadius: 8 }} />
      <p class="small">
        흰 점 = 안정 사진의 위치(머리 움직임 보정), 화살표 = 표정에서 움직인 방향과 크기(×{GAIN} 확대).{' '}
        {METHOD.map((m) => (
          <span key={m.k} style={{ color: m.color, fontWeight: 600, marginRight: 8 }}>
            ■ {m.label}
          </span>
        ))}
      </p>
      <table class="small" style={{ width: '100%' }}>
        <thead>
          <tr>
            <th align="left">방법</th>
            <th>마비측 움직임</th>
            <th>건측 움직임</th>
            <th>비율</th>
          </tr>
        </thead>
        <tbody>
          {METHOD.map((m) => {
            const e = row.exc[m.k];
            const ratio = m.k === 'det' ? row.ratio : m.k === 'trk' ? row.trk : row.geo;
            return (
              <tr key={m.k} style={{ color: m.color }}>
                <td>{m.label}</td>
                <td align="center">{e ? e.left.toFixed(3) : '–'}</td>
                <td align="center">{e ? e.right.toFixed(3) : '–'}</td>
                <td align="center">{r3(ratio)}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export function Bench() {
  const [rows, setRows] = useState<Row[] | null>(null);
  const [msg, setMsg] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [sel, setSel] = useState<number | null>(null);
  const [ignoreGate, setIgnoreGate] = useState(false);

  const run = async () => {
    setBusy(true);
    setError(null);
    try {
      const { sets } = await getJson<{ sets: BenchSet[] }>('manifest.json').catch(() => {
        throw new Error('manifest');
      });
      const result = await runBench(sets, setMsg, ignoreGate);
      // Dev automation (headless runs read the rows without the CSV download).
      (window as unknown as { __bench?: Row[] }).__bench = result;
      setRows(result);
      setMsg('');
    } catch (e) {
      setError(
        e instanceof Error && e.message === 'manifest'
          ? 'public/_bench/manifest.json이 없습니다. tools/blender/bench_render.py로 먼저 렌더하세요.'
          : `분석 실패: ${String(e)}`,
      );
    } finally {
      setBusy(false);
    }
  };

  const save = () => {
    if (!rows) return;
    const cols = columns(extRuns(rows));
    const csv = [cols.map(([h]) => h).join(','), ...rows.map((r) => cols.map(([, f]) => csvCell(f(r))).join(','))].join('\n');
    download(`bench-${new Date().toISOString().slice(0, 16).replace(/[:T]/g, '')}.csv`, '﻿' + csv, 'text/csv;charset=utf-8');
  };

  const base = rows?.filter((r) => r.variant === 'base' && r.condition === 'baseline') ?? [];
  const byTask = MOVEMENT_TASKS.map((t) => {
    const rs = base.filter((r) => r.task === t);
    const mae = (f: (r: Row) => number | null) => {
      const v = rs.map(f).filter((x): x is number => x != null);
      return v.length ? v.reduce((s, x) => s + Math.abs(x), 0) / v.length : null;
    };
    const lm = rs.map((r) => diff(r.ratio, r.geo)).filter((x): x is number => x != null);
    return {
      t,
      n: lm.length,
      pass: lm.filter((x) => Math.abs(x) <= TOL).length,
      lm: mae((r) => diff(r.ratio, r.geo)),
      def: mae((r) => diff(r.geo, r.w)),
      trk: mae((r) => diff(r.trk, r.geo)),
      total: mae((r) => diff(r.ratio, r.w)),
    };
  });
  const runs = extRuns(rows ?? []);
  const present = methodsOf(runs).filter((M) => rows?.some((r) => M.ratio(r) != null));
  const bob = rows?.filter((r) => r.variant === 'base' && r.w != null) ?? [];
  const maeW = (rs: Row[], M: Method) => {
    const v = rs.map((r) => diff(M.ratio(r), r.w)).filter((x): x is number => x != null);
    return v.length ? v.reduce((a, x) => a + Math.abs(x), 0) / v.length : null;
  };
  const avgMs = (v: (number | null | undefined)[]) => {
    const x = v.filter((y): y is number => y != null);
    return x.length ? x.reduce((a, b) => a + b, 0) / x.length : null;
  };
  const msOf = (k: string) =>
    k === 'trk' ? avgMs((rows ?? []).map((r) => r.trkMs)) : runs.includes(k) ? avgMs((rows ?? []).map((r) => r.extMs[k])) : null;
  const smile = rows?.filter((r) => r.task === 'smile') ?? [];
  const neg = smile.filter((r) => r.variant === 'base');
  const pos = smile.filter((r) => !['base', 'orig', 'half'].includes(r.variant));
  const hasEye = (s: string) => s.includes('eye');
  // Half-synthesis (real faces): static half should read 0, moving half should keep the original's movement.
  const halves = MOVEMENT_TASKS.flatMap((t) => {
    const pairs = (rows ?? [])
      .filter((r) => r.variant === 'half' && r.task === t)
      .map((h) => [h, rows!.find((o) => o.variant === 'orig' && o.person === h.person && o.task === t)] as const)
      .filter((p): p is readonly [Row, Row] => !!p[1]);
    if (!pairs.length) return [];
    const mean = (v: number[]) => (v.length ? v.reduce((a, b) => a + b, 0) / v.length : null);
    return present.filter((M) => M.k !== 'geo').map((M) => {
      const ok = pairs.filter(([h, o]) => M.exc(h) && M.exc(o));
      const oR = mean(ok.map(([, o]) => M.exc(o)!.right));
      return {
        t,
        m: M.label,
        n: ok.length,
        half: mean(
          ok
            .map(([h]) => M.ratio(h))
            .filter((x): x is number => x != null)
            .map(Math.abs),
        ),
        orig: mean(ok.map(([, o]) => M.ratio(o)).filter((x): x is number => x != null)),
        leak: oR ? mean(ok.map(([h]) => M.exc(h)!.left))! / oR : null,
        keep: oR ? mean(ok.map(([h]) => M.exc(h)!.right))! / oR : null,
      };
    });
  });
  const pct = (x: number | null) => (x == null ? '–' : `${Math.round(100 * x)}%`);

  return (
    <>
      <AppBar title="3D 조건별 측정 시험" sub="개발 전용 · 합성 마비 얼굴(정답 비율 w)" onBack />
      <main class="main">
        <div class="card tight">
          <Notice>
            <span class="small">
              public/_bench의 렌더를 사진 세트 분석과 같은 경로로 측정합니다. 마비 쪽 = 왼쪽. <b>기하 정답</b>은 안정 사진의 랜드마크를 3D
              메시에 고정해 표정까지 따라간 점으로 같은 분석을 한 값(랜드마크 검출이 완벽할 때의 비율)입니다. 검출 − 기하 = 랜드마크 모델
              오차, 기하 − w = 측정 정의와 표정 키의 차이.
            </span>
          </Notice>
        </div>
        <div class="row" style={{ gap: 8 }}>
          <button class="btn primary" disabled={busy} onClick={run}>
            {busy ? '분석 중…' : rows ? '다시 분석' : '분석 시작'}
          </button>
          <button class="btn" disabled={!rows || busy} onClick={save}>
            CSV 저장
          </button>
          <label class="small" title="게이트에 걸린 사진도 측정합니다. 게이트 열은 실제 판정 그대로이며, 결과는 참고용입니다.">
            <input type="checkbox" checked={ignoreGate} disabled={busy} onChange={(e) => setIgnoreGate(e.currentTarget.checked)} /> 게이트
            무시(연구용)
          </label>
        </div>
        {msg && <p class="small muted">{msg}</p>}
        {error && <Notice tone="danger">{error}</Notice>}
        {rows && sel != null && rows[sel] && <Overlay row={rows[sel]!} onClose={() => setSel(null)} />}
        {rows && (
          <>
            <div class="card tight">
              <h3>기준 조건 요약 (|검출 − 기하| ≤ {TOL})</h3>
              <table class="small" style={{ width: '100%' }}>
                <thead>
                  <tr>
                    <th align="left">과제</th>
                    <th>통과</th>
                    <th>|검출−기하|</th>
                    <th>|기하−w|</th>
                    <th>|검출−w|</th>
                    <th>|추적−기하|</th>
                  </tr>
                </thead>
                <tbody>
                  {byTask.map((b) => (
                    <tr key={b.t}>
                      <td>{TASK_SHORT[b.t]}</td>
                      <td align="center">
                        {b.pass}/{b.n}
                      </td>
                      <td align="center">{r3(b.lm)}</td>
                      <td align="center">{r3(b.def)}</td>
                      <td align="center">{r3(b.total)}</td>
                      <td align="center">{r3(b.trk)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <p class="small">
                연합운동(웃기, 눈): 위양성 {neg.filter((r) => hasEye(r.synk)).length}/{neg.length}, 양성 대조 검출{' '}
                {pos.filter((r) => hasEye(r.synk)).length}/{pos.length} (기하: 위양성 {neg.filter((r) => hasEye(r.geoSynk)).length}, 검출{' '}
                {pos.filter((r) => hasEye(r.geoSynk)).length}; 추적: 위양성 {neg.filter((r) => hasEye(r.trkSynk)).length}, 검출{' '}
                {pos.filter((r) => hasEye(r.trkSynk)).length})
              </p>
            </div>
            {present.length > 2 && (
              <div class="card tight">
                <h3>추적 방법 비교 (|비율 − w|, 합성 캐릭터)</h3>
                <table class="small" style={{ width: '100%' }}>
                  <thead>
                    <tr>
                      <th align="left">방법</th>
                      {MOVEMENT_TASKS.map((t) => (
                        <th key={t}>{TASK_SHORT[t]}</th>
                      ))}
                      <th>고개 조건</th>
                      <th>ms/장</th>
                    </tr>
                  </thead>
                  <tbody>
                    {present.map((M) => (
                      <tr key={M.k}>
                        <td>{M.label}</td>
                        {MOVEMENT_TASKS.map((t) => (
                          <td key={t} align="center">
                            {r3(maeW(bob.filter((r) => r.condition === 'baseline' && r.task === t), M))}
                          </td>
                        ))}
                        <td align="center">{r3(maeW(bob.filter((r) => r.condition !== 'baseline' && r.task !== 'pucker'), M))}</td>
                        <td align="center">{msOf(M.k) == null ? '–' : msOf(M.k)!.toFixed(1)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                <p class="small muted">
                  과제 열 = 기준 조건(정면), 고개 조건 = 좌우·위아래·기울기 조건의 네 과제 평균. 앱 추적 시간은 이 브라우저, 외부 추적기는 GPU(RTX 4060) 기준.
                </p>
              </div>
            )}
            {halves.length > 0 && (
              <div class="card tight">
                <h3>실제 얼굴 절반 합성 (마비측 = 안정 사진, 정답 비율 0)</h3>
                <table class="small" style={{ width: '100%' }}>
                  <thead>
                    <tr>
                      {['과제', '방법', 'n', '원본 비율(건강)', '|합성 비율|', '마비측 누설', '건측 유지'].map((h) => (
                        <th key={h}>{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {halves.map((h) => (
                      <tr key={h.t + h.m}>
                        <td>{TASK_SHORT[h.t]}</td>
                        <td>{h.m}</td>
                        <td>{h.n}</td>
                        <td>{r3(h.orig)}</td>
                        <td>{r3(h.half)}</td>
                        <td>{pct(h.leak)}</td>
                        <td>{pct(h.keep)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                <p class="small muted">
                  누설 = 합성 사진의 마비측 움직임 ÷ 원본 건측 움직임(정답 0 %). 유지 = 합성 건측 ÷ 원본 건측(정답 100 %).
                </p>
              </div>
            )}
            <div style={{ overflowX: 'auto' }}>
              <table class="small" style={{ borderCollapse: 'collapse', whiteSpace: 'nowrap' }}>
                <thead>
                  <tr>
                    {[
                      '조건',
                      '변형',
                      '과제',
                      'w',
                      '검출',
                      '기하',
                      '검출−기하',
                      '기하−w',
                      '추적',
                      '추적−기하',
                      '마비/건측 움직임(검출·기하·추적)',
                      'yaw/pitch/roll',
                      '게이트',
                      '연합운동(검출 | 기하 | 추적)',
                    ].map((h) => (
                      <th key={h} style={{ padding: '2px 6px' }}>
                        {h}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r, i) => {
                    const lm = diff(r.ratio, r.geo);
                    return (
                      <tr
                        key={i}
                        onClick={() => setSel(sel === i ? null : i)}
                        style={{
                          cursor: 'pointer',
                          background: sel === i ? 'var(--surface-2, #eef)' : undefined,
                          color: lm != null && Math.abs(lm) > TOL ? 'var(--danger, #c33)' : undefined,
                        }}
                      >
                        <td style={{ padding: '2px 6px' }}>
                          {r.person}·{r.condition}
                        </td>
                        <td>{r.variant}</td>
                        <td>{TASK_SHORT[r.task]}</td>
                        <td align="right">{r.w ?? '–'}</td>
                        <td align="right">{r3(r.ratio)}</td>
                        <td align="right">{r3(r.geo)}</td>
                        <td align="right">{r3(lm)}</td>
                        <td align="right">{r3(diff(r.geo, r.w))}</td>
                        <td align="right">
                          {r3(r.trk)}
                          {r.kept != null && <span class="muted"> ({Math.round(r.kept * 100)}%)</span>}
                        </td>
                        <td align="right">{r3(diff(r.trk, r.geo))}</td>
                        <td>
                          {(['det', 'geo', 'trk'] as const)
                            .map((m) => (r.exc[m] ? `${r.exc[m]!.left.toFixed(3)}/${r.exc[m]!.right.toFixed(3)}` : '–'))
                            .join(' · ')}
                        </td>
                        <td align="right">
                          {r.yaw.toFixed(0)}/{r.pitch.toFixed(0)}/{r.roll.toFixed(0)}
                        </td>
                        <td title={r.gateReasons}>{r.gateOk ? '통과' : `✕ ${r.gateReasons}`}</td>
                        <td>
                          {r.synk} | {r.geoSynk} | {r.trkSynk}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </>
        )}
      </main>
    </>
  );
}
